import{_ as r,C as c,o as b,c as G,j as l,a as n,t as d,E as a,ar as i}from"./chunks/framework.CIfak1z2.js";const F=JSON.parse('{"title":"Typesense API Reference for v30.2","description":"","frontmatter":{"sitemap":{"priority":0.7},"head":[["link",{"rel":"canonical","href":"https://typesense.org/docs/30.2/api/index.html"}],["link",{"rel":"alternate","type":"text/markdown","href":"/docs/30.2/api/README.md"}]]},"headers":[],"relativePath":"30.2/api/index.md","filePath":"30.2/api/README.md","lastUpdated":1776416488000,"typesenseVersion":"30.2","markdown":"","markdownCopyTabGroups":[],"markdownCopyLanguages":[],"markdownUrl":"/30.2/api/README.md"}'),Z={name:"30.2/api/index.md"},m={class:"flex flex-wrap items-center justify-between gap-4"},h={id:"typesense-api-reference-for-v-page-typesenseversion",tabindex:"-1"},u={id:"what-s-new",tabindex:"-1"},y={id:"new-features",tabindex:"-1"},W={id:"enhancements",tabindex:"-1"},B={id:"bug-fixes",tabindex:"-1"},p={id:"deprecations-behavior-changes",tabindex:"-1"},I={id:"upgrading",tabindex:"-1"},V={id:"downgrading",tabindex:"-1"};function Y(t,e,X,v,R,H){const s=c("MarkdownActions"),o=c("CopySectionButton"),g=c("RedirectOldLinks");return b(),G("div",null,[l("div",m,[l("h1",h,[n("Typesense API Reference for v"+d(t.$page.typesenseVersion)+" ",1),e[0]||(e[0]=l("a",{class:"header-anchor",href:"#typesense-api-reference-for-v-page-typesenseversion","aria-label":'Permalink to "Typesense API Reference for v{{ $page.typesenseVersion }}"'},"​",-1))]),a(s)]),e[15]||(e[15]=l("div",{hidden:""},[l("p",null,[l("strong",null,"AI agents and LLMs:"),n(" before exploring further, fetch the full index of Typesense documentation with descriptions at "),l("a",{href:"https://typesense.org/docs/llms.txt"},"https://typesense.org/docs/llms.txt"),n(".")])],-1)),e[16]||(e[16]=l("p",null,"This section of the documentation details all the API Endpoints available in Typesense and all the parameters you can use with them.",-1)),e[17]||(e[17]=l("p",null,"Use the links on the side navigation bar to get to the appropriate section you're looking for.",-1)),e[18]||(e[18]=l("p",null,[n("To learn how to install and run Typesense, see the "),l("a",{href:"https://typesense.org/docs/guide/",target:"_blank",rel:"noreferrer"},"Guide section"),n(" instead.")],-1)),e[19]||(e[19]=l("br",null,null,-1)),l("h2",u,[e[1]||(e[1]=n("What's new ",-1)),e[2]||(e[2]=l("a",{class:"header-anchor",href:"#what-s-new","aria-label":`Permalink to "What's new"`},"​",-1)),a(o,{headingText:"What's new",headingLevel:2})]),e[20]||(e[20]=l("p",null,[n("The "),l("strong",null,"v30"),n(" release contains new features, enhancements, performance improvements, bug fixes and important API changes for synonyms, curation rules and analytics rules.")],-1)),e[21]||(e[21]=l("p",null,[n("This particular "),l("strong",null,"v30.2"),n(" release primarily contains bug fixes, performance improvements, and operational hardening across search, highlighting, filtering, faceting, vector search, and multi-search / conversation search flows.")],-1)),l("h3",y,[e[3]||(e[3]=n("New Features ",-1)),e[4]||(e[4]=l("a",{class:"header-anchor",href:"#new-features","aria-label":'Permalink to "New Features"'},"​",-1)),a(o,{headingText:"New Features",headingLevel:3})]),e[22]||(e[22]=i('<ul><li><strong>Diversify Search Results</strong>: Using Maximum Marginal Relevance (MMR), you can now diversify the top 250 hits on a pre-defined similarity metric. <a href="https://typesense.org/docs/30.1/api/curation.html#diversify-results" target="_blank" rel="noreferrer">(Docs)</a></li><li><strong>Global Synonyms</strong>: Synonyms are now top-level resources, and can be shared between collections. <a href="https://typesense.org/docs/30.1/api/synonyms.html" target="_blank" rel="noreferrer">(Docs)</a></li><li><strong>Global Curation Rules</strong>: Curations are also top-level resources now, and can be shared between multiple collections. <a href="https://typesense.org/docs/30.1/api/curation.html" target="_blank" rel="noreferrer">(Docs)</a></li><li><strong>New features in JOINs</strong>: <ul><li><code>facet_by</code> now supports JOINed reference fields. <a href="https://typesense.org/docs/30.1/api/search.html#facet-referencing" target="_blank" rel="noreferrer">(Docs)</a></li><li>Fetch related docs count for a document in a joined collection with the <code>include_fields</code> param. <a href="https://typesense.org/docs/30.1/api/joins.html#get-number-of-related-documents" target="_blank" rel="noreferrer">(Docs)</a></li><li>Support sorting and limit on joined fields with <code>include_fields</code> parameter. <a href="https://typesense.org/docs/30.1/api/joins.html#Sorting-and-limiting-on-joined-collection-docs" target="_blank" rel="noreferrer">(Docs)</a></li><li>Support for altering reference fields in the collection schema.</li><li>New <code>cascade_delete: false</code> JOIN parameter for a <code>reference</code> field, to override the default behavior of document being cascade deleted in case all the documents it references are deleted. Requires <code>async_reference</code> parameter to be <code>true</code>. <a href="https://typesense.org/docs/30.1/api/joins.html#cascade-delete" target="_blank" rel="noreferrer">(Docs)</a></li></ul></li><li><strong>New features in Union Search</strong>: <ul><li>Support for <code>group_by</code> with Union search. <a href="https://typesense.org/docs/30.1/api/federated-multi-search.html#grouping-with-union" target="_blank" rel="noreferrer">(Docs)</a></li><li>Support for the <code>pinned_hits</code> search parameter in Union search.</li><li>Support for filtering out duplicates when using Union search with a new flag called <code>remove_duplicates</code>. <a href="https://typesense.org/docs/30.1/api/federated-multi-search.html#removing-duplicates-in-union-search" target="_blank" rel="noreferrer">(Docs)</a></li></ul></li><li><strong>Facet Sampling</strong>: Make facet sampling dynamic using the new <code>facet_sample_slope</code> search parameter. <a href="https://typesense.org/docs/30.1/api/search.html#faceting-parameters" target="_blank" rel="noreferrer">(Docs)</a></li><li><strong>IPv6 Support</strong>: Typesense now supports binding to and serving requests over IPv6 addresses, enabling seamless integration and connectivity in modern IPv6-only or dual-stack networks.</li></ul>',1)),l("h3",W,[e[5]||(e[5]=n("Enhancements ",-1)),e[6]||(e[6]=l("a",{class:"header-anchor",href:"#enhancements","aria-label":'Permalink to "Enhancements"'},"​",-1)),a(o,{headingText:"Enhancements",headingLevel:3})]),e[23]||(e[23]=i('<ul><li>Support for (optionally) copying documents when cloning collections. <a href="https://typesense.org/docs/30.1/api/collections.html#clone-collection-with-documents" target="_blank" rel="noreferrer">(Docs)</a></li><li>Support for <code>!</code> as a standalone negation operator in filters, allowing <code>field:![value]</code> syntax as an alternative to <code>field:!=[value]</code>.</li><li>Support for Azure OpenAI models in Natural Language Search. <a href="https://typesense.org/docs/30.1/api/natural-language-search.html#supported-model-types" target="_blank" rel="noreferrer">(Docs)</a></li><li>Support for GCP service account authentication in Natural Language Search models. <a href="https://typesense.org/docs/30.1/api/natural-language-search.html#supported-model-types" target="_blank" rel="noreferrer">(Docs)</a></li><li>Support for GCP service account authentication for auto-embedding with GCP models. <a href="https://typesense.org/docs/30.1/api/vector-search.html#service-account-authentication" target="_blank" rel="noreferrer">(Docs)</a></li><li>Configurable token truncation for string fields to improve exact match filtering on long strings, using the new <code>truncate</code> parameter in the collection schema. <a href="https://typesense.org/docs/30.1/api/collections.html#field-parameters" target="_blank" rel="noreferrer">(Docs)</a></li><li>Return an error message when a field is declared that references another field of the same collection.</li><li>New <code>group_max_candidates</code> search parameter which overrides the behavior of <code>group_by</code> queries introduced in <a href="https://typesense.org/docs/29.0/api/#deprecations-behavior-changes" target="_blank" rel="noreferrer">v29.0</a> where <code>found</code> value is an approximation. When <code>group_max_candidates</code> is passed, <code>found</code> will be accurate up until its value. <a href="https://typesense.org/docs/30.1/api/search.html#grouping-parameters" target="_blank" rel="noreferrer">(Docs)</a></li><li>Allow non-indexed nested fields to still be marked as required.</li><li>Improved synonym matching logic: Previously, synonym matches with a higher number of tokens (query/synonym) would be ranked higher. Now, matches are ranked by how well they match the query/synonyms overall, not just by the number of matched tokens.</li><li>Use Transliterator objects pool to enhance tokenization performance of Cyrillic and Chinese languages.</li><li>Support for dynamic <code>facet_return_parent</code> fields. <a href="https://typesense.org/docs/30.1/api/search.html#faceting-parameters" target="_blank" rel="noreferrer">(Docs)</a></li><li>Support for sending an empty array to avoid embedding generation for an optional auto embedding field when indexing a document.</li><li>Highlight the actual search query when augmenting the search query with Natural Language search.</li><li>Enhance image embedding models support by adding CLIP Multilingual Model support</li><li>Support for synonym matching in curations <a href="https://typesense.org/docs/30.1/api/curation.html#synonyms-with-curations" target="_blank" rel="noreferrer">(Docs)</a></li><li>Support stemming with curations <a href="https://typesense.org/docs/30.1/api/curation.html#stemming-with-curations" target="_blank" rel="noreferrer">(Docs)</a></li><li><strong>[v30.2]</strong> Improved search concurrency and memory efficiency by reducing lock contention during searches.</li><li><strong>[v30.2]</strong> Improved <code>delete-by-query</code> performance by batching index removals while preserving per-document behavior for cascaded deletes.</li><li><strong>[v30.2]</strong> Added pre-emptive logging for long-running queries to make production debugging easier.</li><li><strong>[v30.2]</strong> Increased timeouts for model downloads and embedding model configuration fetches to better accommodate slower remote providers.</li><li><strong>[v30.2]</strong> Return a clearer error message when a <code>group_by</code> field cannot be resolved.</li></ul>',1)),l("h3",B,[e[7]||(e[7]=n("Bug Fixes ",-1)),e[8]||(e[8]=l("a",{class:"header-anchor",href:"#bug-fixes","aria-label":'Permalink to "Bug Fixes"'},"​",-1)),a(o,{headingText:"Bug Fixes",headingLevel:3})]),e[24]||(e[24]=i("<ul><li>Fix parsing of <code>_eval()</code> expressions when backticks are used to wrap strings containing parentheses.</li><li>Ensure unique analytics IDs are generated when queries differ by <code>filter_by</code> or <code>analytics_tag</code> metadata to prevent aggregation issues.</li><li>Fix search highlighting to use field-specific token separators instead of collection-level ones for consistent behavior.</li><li>Return <code>201</code> status code when creating conversational models, personalization models, or natural language search models to follow REST conventions.</li><li>Fix custom OpenAI-compatible endpoint URLs not being used for auto-embedding.</li><li>Fix schema updates with embedding fields incorrectly requiring <code>api_key</code> validation for local models.</li><li>Fix console logging to output info messages to stdout and warnings/errors to stderr instead of all to stderr.</li><li>Fix phrase query highlighting to highlight only exact phrase matches instead of every individual keyword occurrence.</li><li>Set user agent when initializing HTTP client for external API calls.</li><li>Fix hyphen handling in negation searches to only apply special treatment when token starts with <code>-</code>.</li><li>Fix query sub-tokenization to respect field-level <code>symbols_to_index</code> and <code>token_separators</code> configuration.</li><li>Fix union search pagination bug where global pagination parameters were not passed to individual queries.</li><li>Fix missing groups in case of high cardinality fields.</li><li>Fix various deadlock scenarios related to async reference fields.</li><li>Fix an edge case in <code>group_by</code> query along with <code>infix</code> search.</li><li>Fix non-deterministic bucketing order when combining <code>group_by</code> with text match score bucketing, ensuring stable group pagination.</li><li>Support <code>id:![...]</code> negation syntax for id filters.</li><li>Fix remote embedder cache key handling for matryoshka models with different <code>num_dim</code> values to prevent dimension mismatches.</li><li>Fix nested array highlights to respect <code>highlight_affix_num_tokens</code> for single-token matches.</li><li>Fix phrase highlighting in nested array fields to return all matching snippets.</li><li>Fix a crash while searching when updates are happening in parallel.</li><li>Fixed the override matching for wildcard queries, dynamic filter, dynamic sort, and placeholders.</li><li>Fix sort using <code>_eval()</code> for <code>id</code> fields.</li><li>Fix missing vector distance in results when doing hybrid search with union search.</li><li>Fix missing results when querying a stemmed field with <code>drop_tokens_threshold</code> set.</li><li>Fix an edge case where field name can be empty.</li><li>Fix synonym resolution when <code>synonym_prefix</code> is disabled.</li><li>Fix allowing the addition of the same field multiple times when altering the collection.</li><li>Fix an edge case that enables using resolved synonyms as prefixes when prefix search is enabled.</li><li>Fix adding the field to schema despite an error, when sorting is enabled for a field that has <code>auto</code> as its type.</li><li>Fix <code>max_bytes</code> parameters usage for the OpenAI&#39;s o-series and GPT-5 models.</li><li>Prevent usage of <code>temperature</code> parameter for the o-series and GPT-5 models since it is not supported.</li><li>Fix curation rule matching when doing semantic search with embedding generation.</li><li>Fix rocksdb params assignment</li><li>Fix missing joined collection fields in pinned hits</li><li>Fix blocking indexing while generating embeddings.</li><li>Fix issues of using outdated schemas when altering operations is ongoing while indexing documents.</li><li>Fix curations with rerank_hybrid_matches</li><li>Fix uninitialized analytics manager crash</li><li>Validate that curation rules with <code>match</code> also include <code>query</code>, returning <code>400</code> otherwise.</li><li>Fix dropping nested object fields to only remove dot-delimited children, preserving similarly-prefixed top-level fields.</li><li>Fix conversation and natural language search model updates when the model ID changes, returning <code>409</code> on ID conflicts.</li><li><strong>[v30.1]</strong> Fixed precision issue with search latency metric in <code>/stats.json</code> endpoint.</li><li><strong>[v30.2]</strong> Fixed incorrect handling of numeric <code>!=</code> filters in both lazy and eager filter execution, including explicit not-equals lists on range-indexed numeric fields.</li><li><strong>[v30.2]</strong> Fixed highlighting to correctly mark single-token phrase matches and to avoid race conditions during union searches that run alongside concurrent writes.</li><li><strong>[v30.2]</strong> Fixed missing <code>synonyms</code>, <code>stem</code>, and <code>stemming_dictionary</code> fields in curation GET responses.</li><li><strong>[v30.2]</strong> Fixed a number of edge cases in diversity search.</li><li><strong>[v30.2]</strong> Fixed union search deduplication so curated pinned hits are no longer collapsed.</li><li><strong>[v30.2]</strong> Fixed a bug related to reference faceting.</li><li><strong>[v30.2]</strong> Fixed vector search behavior so zero-match phrase queries still preserve vector search results.</li><li><strong>[v30.2]</strong> Fixed scoped API key handling so embedded collection parameters can supply a missing collection in multi-search requests.</li><li><strong>[v30.2]</strong> Fixed conversation search error handling so failed searches do not incorrectly reuse the first search collection.</li><li><strong>[v30.2]</strong> Fixed search cache keying so scoped API key parameters and request-specific embedded params do not collide in the cache.</li><li><strong>[v30.2]</strong> Fixed JSON response escaping by using <code>nlohmann::json::dump()</code> when serializing response payloads.</li><li><strong>[v30.2]</strong> Fixed <code>/health</code> responsiveness during heavy bulk inserts by routing health checks to the meta thread pool.</li><li><strong>[v30.2]</strong> Fixed HTTP/2 async import teardown on early exit.</li></ul>",1)),l("h3",p,[e[9]||(e[9]=n("Deprecations / behavior changes ",-1)),e[10]||(e[10]=l("a",{class:"header-anchor",href:"#deprecations-behavior-changes","aria-label":'Permalink to "Deprecations / behavior changes"'},"​",-1)),a(o,{headingText:"Deprecations / behavior changes",headingLevel:3})]),e[25]||(e[25]=i('<ul><li>⚠️ <strong>Synonyms</strong> are no longer nested under Collections. We now have a top-level resource called a &quot;<strong>Synonym Set</strong>&quot; which is a list of synonyms that can be attached to one or more collections, or can be dynamically sent as a search parameter. Existing synonyms will be auto-migrated to synonym sets automatically on upgrading. <a href="https://typesense.org/docs/30.1/api/synonyms.html" target="_blank" rel="noreferrer">(Docs)</a></li><li>⚠️ <strong>Synonym API Key Actions</strong> have changed. Since the synonym API route changed from <code>/collections/{collection}/synonyms</code> to <code>/synonym_sets</code>, API keys scoped to <code>synonyms:*</code> actions will <strong>not</strong> grant access to the new synonym set endpoints (resulting in <code>401 Unauthorized</code>). You need to create new API keys using <code>synonym_sets:*</code> actions instead (e.g. <code>synonym_sets:get</code>, <code>synonym_sets:list</code>, <code>synonym_sets:create</code>, <code>synonym_sets:delete</code>). Since there is no update endpoint for API keys, you will need to create new keys and then delete the old ones. The old <code>synonyms:*</code> actions still apply to collection-level synonym endpoints. <a href="https://typesense.org/docs/30.1/api/api-keys.html#synonym-set-actions" target="_blank" rel="noreferrer">(Docs)</a></li><li>⚠️ <strong>Overrides</strong> (aka Curation Rules) are no longer nested under Collections. Similar to synonym sets, we now have a top-level resource called a &quot;<strong>Curation Set</strong>&quot; that can be attached to one or more collections, or can be dynamically sent as a search parameter. Existing overrides will be auto-migrated to curation sets automatically on upgrading. The <a href="https://typesense.org/docs/29.0/api/search.html#ranking-and-sorting-parameters" target="_blank" rel="noreferrer"><code>override_tags</code></a> parameter has also been renamed to <code>curation_tags</code>. <a href="https://typesense.org/docs/30.1/api/curation.html" target="_blank" rel="noreferrer">(Docs)</a></li><li>⚠️ The structure of <strong>Analytics Rules</strong> has changed. Old rules will be automatically migrated to the new structure internally. Read more here. <a href="https://typesense.org/docs/30.1/api/analytics-query-suggestions.html" target="_blank" rel="noreferrer">(Docs)</a></li><li>The export endpoint doesn&#39;t stop streaming the response if an error is encountered while loading a document from disk. The error is logged and is also returned in the response stream.</li><li>Collections having references to each other are not allowed. If mutual reference is detected, the reference field will not be indexed.</li></ul>',1)),l("h2",I,[e[11]||(e[11]=n("Upgrading ",-1)),e[12]||(e[12]=l("a",{class:"header-anchor",href:"#upgrading","aria-label":'Permalink to "Upgrading"'},"​",-1)),a(o,{headingText:"Upgrading",headingLevel:2})]),l("p",null,"Before upgrading your existing Typesense cluster to v"+d(t.$page.typesenseVersion)+", please review the behavior changes above to prepare your application for the upgrade.",1),e[26]||(e[26]=i('<p>We&#39;d recommend testing on your development / staging environments before upgrading.</p><p>Follow this <a href="https://typesense.org/docs/guide/updating-typesense.html" target="_blank" rel="noreferrer">upgrade guide</a>, depending on your mode of deployment.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Breaking Changes</p><p>Please make sure to <strong>update your client libraries</strong> to the latest version, <strong>review the specific documentation links provided above</strong> and make any required changes to your code base if you programmatically create these resources using the API, before upgrading to this version. If self-hosting, <a href="https://typesense.org/docs/30.1/api/cluster-operations.html#create-snapshot-for-backups" target="_blank" rel="noreferrer"><strong>perform a snapshot</strong></a> before upgrading for the Synonyms &amp; Overrides to be migrated to v30.</p></div>',3)),l("h2",V,[e[13]||(e[13]=n("Downgrading ",-1)),e[14]||(e[14]=l("a",{class:"header-anchor",href:"#downgrading","aria-label":'Permalink to "Downgrading"'},"​",-1)),a(o,{headingText:"Downgrading",headingLevel:2})]),e[27]||(e[27]=l("p",null,"If you use synonyms, overrides (curation rules) or analytics rules in previous versions of Typesense, we will auto-migrate them to the new resources (Synonym Sets, Curation Sets and the new format for analytics rules) on upgrading. However, if you make any changes to these resources, and then downgrade later, those changes will not be ported back to the old version after downgrade.",-1)),e[28]||(e[28]=l("p",null,[n("Besides the above caveat, you can safely downgrade to any version above "),l("code",null,"v27"),n(".")],-1)),a(g)])}const z=r(Z,[["render",Y]]);export{F as __pageData,z as default};
